<script setup lang="ts">
import {money,localLabel} from '#shared/booking'
const route=useRoute()
type View={reference:string;startAt:number;endAt:number;date:string;amount:number;name:string;address:string;notes:string;status:string;paymentStatus:string;lines:{name:string;quantity:number;price_cents:number}[]}
const {data:booking,error:loadError}=await useFetch<View>('/api/bookings/'+route.params.token)
useSeoMeta({title:'Tu reserva · Masajes Aurora',robots:'noindex, nofollow'})
const status=computed(()=>({confirmed:'Reserva confirmada',completed:'Sesión realizada',cancelled:'Reserva cancelada'}[booking.value?.status||'']||''))
</script>
<template><div class="page-shell narrow"><header class="page-header"><BrandLogo /></header><main><h1 class="page-title">{{ status||'Tu reserva' }}</h1><p v-if="loadError" class="notice" role="alert">No hemos podido consultar esta reserva. Comprueba el enlace o contacta con Melba.</p><template v-if="booking"><p class="text-muted mb-6">Referencia {{ booking.reference }}</p><div class="surface"><dl class="summary-list"><div><dt>Fecha</dt><dd>{{ booking.date }}</dd></div><div><dt>Horario</dt><dd>{{ localLabel(booking.startAt) }}–{{ localLabel(booking.endAt) }}</dd></div><div v-for="line in booking.lines" :key="line.name"><dt>{{ line.quantity }} · {{ line.name }}</dt><dd>{{ money(line.quantity*line.price_cents) }}</dd></div><div><dt>Total</dt><dd>{{ money(booking.amount) }}</dd></div><div><dt>Pago</dt><dd>{{ booking.paymentStatus==='paid'?'Pagado en efectivo':'En efectivo el día de la cita' }}</dd></div></dl><p class="mt-5">{{ booking.name }}<br />{{ booking.address }}</p><p v-if="booking.notes" class="mt-3">{{ booking.notes }}</p></div><p v-if="booking.status==='confirmed'" class="mt-6">Hemos preparado el email de confirmación. Si necesitas cambiar o cancelar tu cita, habla con Melba.</p><p v-if="booking.status==='cancelled'" class="mt-5">Puedes <NuxtLink to="/reservar" class="underline">elegir otra sesión</NuxtLink>.</p><a href="https://wa.me/34644798063" class="text-link mt-8 inline-block">Contactar con Melba</a></template></main></div></template>

